package watch

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// OpenCode has no hook config to merge: a plugin file in its plugins
// folder is loaded on start. Rex writes one small generated file there,
// and it only ever pipes events to `rex ingest --source opencode`.

const opencodeMarker = "// generated by rex — safe to delete"

// openCodeTypes are the payload types the plugin sends.
var openCodeTypes = map[string]bool{
	"chat.message": true, "message.part.updated": true, "session.idle": true, "session.error": true,
	"permission.updated": true, "permission.asked": true, "question.asked": true,
}

// opencodePluginJS is the plugin. It never throws from a hook, never waits
// for rex, and never sets output. Only allow-listed fields leave it: no
// file bodies, diffs, attachments or tool output. A subagent's (child)
// session is agent work: its prompt, replies and turn end are not sent.
// The reply is the last text of a turn, sent with session.idle, as Claude
// Code's Stop does; parts older than the plugin (a fork replays history)
// are skipped.
const opencodePluginJS = opencodeMarker + `
// Pipes OpenCode events to rex, which only watches: https://github.com/luciancheng/rex
import { spawn } from "node:child_process"
const REX = %s
const started = Date.now()
let q = Promise.resolve()
function send(p) {
  let line
  try { line = JSON.stringify(p) + "\n" } catch { return }
  q = q.then(() => new Promise((done) => {
    try {
      const c = spawn(REX, ["ingest", "--source", "opencode"], { stdio: ["pipe", "ignore", "ignore"], windowsHide: true })
      const t = setTimeout(() => { try { c.kill() } catch {} ; done() }, 5000)
      c.on("error", () => { clearTimeout(t); done() })
      c.on("close", () => { clearTimeout(t); done() })
      c.stdin.on("error", () => {})
      c.stdin.end(line)
    } catch { done() }
  })).catch(() => {})
}
const str = (v) => (typeof v === "string" ? v : undefined)
const input = (i = {}) => {
  const out = {}
  for (const k of ["filePath", "path", "command", "description", "pattern", "query", "url", "name", "subagent_type"]) if (str(i[k])) out[k] = i[k]
  if (Array.isArray(i.todos)) out.todos = i.todos.map((t) => ({ content: String(t?.content ?? ""), status: str(t?.status) }))
  return out
}
const files = (m) => Array.isArray(m?.files) ? m.files.map((f) => ({ path: str(f?.movePath) || str(f?.filePath), type: str(f?.type) })).filter((f) => f.path) : undefined
const tool = (s = {}) => ({ status: s.status, input: input(s.input), error: str(s.error), files: files(s.metadata), exit: typeof s.metadata?.exit === "number" ? s.metadata.exit : undefined })
export const RexPlugin = async (ctx) => {
  const cwd = ctx?.directory || ctx?.worktree || ""
  const roles = new Map(), seen = new Set(), children = new Set(), last = new Map()
  return {
    event: async ({ event }) => {
      try {
        const p = event?.properties ?? {}
        switch (event?.type) {
          case "session.created": case "session.updated":
            if (p.info?.id && p.info.parentID) children.add(p.info.id)
            return
          case "message.updated":
            if (p.info?.id) roles.set(p.info.id, p.info.summary || p.info.mode === "compaction" ? "summary" : p.info.role)
            return
          case "message.part.updated": {
            const part = p.part
            if (!part) return
            const end = part.time?.end ?? part.state?.time?.end
            if (typeof end === "number" && end < started - 5000) return
            if (part.type === "tool") {
              const st = part.state?.status, key = part.callID + ":" + st
              if (["running", "completed", "error"].includes(st) && !seen.has(key)) {
                seen.add(key)
                send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: "tool", tool: part.tool, callID: part.callID, state: tool(part.state) } })
              }
              return
            }
            if (children.has(part.sessionID) || !part.time?.end || part.synthetic || part.ignored || roles.get(part.messageID) !== "assistant" || seen.has(part.id)) return
            seen.add(part.id)
            if (part.type === "reasoning") send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: "reasoning", text: str(part.text) } })
            if (part.type === "text") last.set(part.sessionID, str(part.text))
            return
          }
          case "session.idle": {
            if (children.has(p.sessionID)) return
            const text = last.get(p.sessionID)
            last.delete(p.sessionID)
            send({ type: event.type, cwd, sessionID: p.sessionID, text })
            return
          }
          case "session.error":
            if (children.has(p.sessionID)) return
            send({ type: event.type, cwd, sessionID: p.sessionID, error: { name: str(p.error?.name), message: str(p.error?.data?.message) ?? str(p.error?.message) } })
            return
          case "permission.updated": case "permission.asked":
            send({ type: event.type, cwd, properties: { title: str(p.title), type: str(p.type), permission: str(p.permission), patterns: Array.isArray(p.patterns) ? p.patterns.filter(str) : undefined, sessionID: str(p.sessionID) } })
            return
          case "question.asked":
            send({ type: event.type, cwd, properties: { questions: Array.isArray(p.questions) ? p.questions.map((x) => ({ question: str(x?.question), header: str(x?.header) })) : undefined } })
            return
        }
      } catch {}
    },
    "chat.message": async (inp, output) => {
      try {
        if (children.has(inp?.sessionID)) return
        const text = (output?.parts ?? []).filter((x) => x?.type === "text" && !x.synthetic && !x.ignored).map((x) => x.text).join("\n").trim()
        if (text) send({ type: "chat.message", cwd, sessionID: inp?.sessionID, text })
      } catch {}
    },
  }
}
`

// opencodeDir is OpenCode's config folder: $XDG_CONFIG_HOME/opencode, else
// ~/.config/opencode (on every OS).
func opencodeDir(home string) string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "opencode")
	}
	return filepath.Join(home, ".config", "opencode")
}

func opencodePlugin(home string) string { return filepath.Join(opencodeDir(home), "plugins", "rex.js") }

func opencodeSource(exe string) []byte {
	q, _ := json.Marshal(exe)
	return []byte(fmt.Sprintf(opencodePluginJS, q))
}

// installOpenCode writes the plugin atomically. A rex.js that Rex didn't
// write is left alone.
func installOpenCode(path string, out io.Writer) error {
	want := opencodeSource(rexExecutable())
	if fi, err := os.Lstat(path); err == nil && fi.Mode()&os.ModeSymlink != 0 {
		resolved, err := filepath.EvalSymlinks(path)
		if err != nil {
			return fmt.Errorf("%s is a link to a file that isn't there; fix or remove it first", path)
		}
		path = resolved // a dotfiles symlink stays a symlink
	}
	have, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return err // can't tell whose it is, so it stays
	}
	if err == nil {
		if !bytes.HasPrefix(have, []byte(opencodeMarker)) {
			return fmt.Errorf("%s exists and Rex didn't write it; move it to install the rex plugin", path)
		}
		if bytes.Equal(have, want) {
			fmt.Fprintf(out, "opencode plugin already installed at %s\n", path)
			return nil
		}
	}
	if err := writeFileAtomic(path, want, 0o644); err != nil {
		return err
	}
	fmt.Fprintf(out, "installed opencode plugin at %s (restart OpenCode to load it)\n", path)
	fmt.Fprintf(out, "feed: %s\n", DefaultEventPath())
	return nil
}

func uninstallOpenCode(path string, out io.Writer) error {
	have, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		fmt.Fprintf(out, "opencode: no rex plugin at %s\n", path)
		return nil
	}
	if err != nil {
		return err
	}
	if !bytes.HasPrefix(have, []byte(opencodeMarker)) {
		return fmt.Errorf("%s wasn't written by Rex; leaving it", path)
	}
	target := ""
	if fi, err := os.Lstat(path); err == nil && fi.Mode()&os.ModeSymlink != 0 {
		target, _ = filepath.EvalSymlinks(path)
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	fmt.Fprintf(out, "removed the rex plugin from %s\n", path)
	if target != "" {
		fmt.Fprintf(out, "it was a link; the file it pointed to, %s, is kept\n", target)
	}
	return nil
}

// writeFileAtomic writes data to path through a temp file in the same
// folder, so OpenCode never loads half a plugin.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".rex-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), mode); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

// MapOpenCode maps one payload from the rex plugin.
func MapOpenCode(payload map[string]any) *Event {
	cwd := strField(payload, "cwd")
	event := func(kind, text string, meta map[string]any) *Event {
		if strings.TrimSpace(text) == "" {
			return nil
		}
		ev := NewEvent("opencode", kind, text, meta)
		return &ev
	}
	abs := func(p string) string {
		if p != "" && !filepath.IsAbs(p) && cwd != "" {
			return filepath.Join(cwd, p)
		}
		return p
	}
	switch strField(payload, "type") {
	case "chat.message":
		return event("user", strings.TrimSpace(strField(payload, "text")), nil)
	case "message.part.updated":
		part := asDict(payload["part"])
		switch strField(part, "type") {
		case "reasoning":
			return event("thought", strings.TrimSpace(strField(part, "text")), nil)
		case "tool":
			return openCodeTool(part, abs, event)
		}
	case "session.idle":
		// The turn's last text is its reply, sent with the idle.
		if text, _ := payload["text"].(string); strings.TrimSpace(text) != "" {
			return event("text", strings.TrimSpace(text), nil)
		}
		return event("idle", "turn completed", nil)
	case "session.error":
		e := asDict(payload["error"])
		name, _ := e["name"].(string)
		msg, _ := e["message"].(string)
		if msg == "" {
			msg, _ = asDict(e["data"])["message"].(string)
		}
		switch name {
		case "MessageAbortedError":
			return event("idle", "turn interrupted", map[string]any{"status": "aborted"})
		case "ContextOverflowError":
			return nil // OpenCode compacts and carries on
		}
		if msg == "" {
			msg = name
		}
		if msg == "" {
			return event("error", "session error", nil) // OpenCode's error is optional
		}
		return event("error", "session error: "+firstLine(msg), nil)
	case "permission.updated", "permission.asked":
		props := asDict(payload["properties"])
		text := strField(props, "title")
		if text == "" {
			var patterns []string
			if list, ok := props["patterns"].([]any); ok {
				for _, p := range list {
					if s, ok := p.(string); ok {
						patterns = append(patterns, s)
					}
				}
			}
			text = strings.TrimSpace(strField(props, "permission") + " " + strField(props, "type"))
			if len(patterns) > 0 {
				text += ": " + strings.Join(patterns, ", ")
			}
		}
		return event("question", "permission: "+text, nil)
	case "question.asked":
		props := asDict(payload["properties"])
		return event("question", toolText("question", props), toolMeta("question", ""))
	}
	return nil
}

func openCodeTool(part map[string]any, abs func(string) string, event func(string, string, map[string]any) *Event) *Event {
	tool := strField(part, "tool")
	if tool == "question" {
		return nil // question.asked carries the question itself
	}
	state := asDict(part["state"])
	input := asDict(state["input"])
	status := strField(state, "status")
	var paths []any
	if p := abs(strField(input, "filePath")); p != "" {
		paths = append(paths, p)
	}
	deleted := false
	if files, ok := state["files"].([]any); ok {
		for _, f := range files {
			if v := asDict(f); v != nil {
				if p, _ := v["path"].(string); p != "" {
					paths = append(paths, abs(p))
					deleted = deleted || (len(paths) == 1 && v["type"] == "delete")
				}
			}
		}
	}
	if len(paths) > 1 && paths[0] == paths[1] {
		paths = paths[1:]
	}
	first := ""
	if len(paths) > 0 {
		first = paths[0].(string)
	}
	meta := toolMeta(tool, first)
	if len(paths) > 1 {
		meta["paths"] = paths
	}
	cmd := strings.TrimSpace(asCommand(input["command"]))
	edit := IsFileEditTool(tool) || tool == "apply_patch"
	switch status {
	case "running":
		switch {
		case IsShellTool(tool):
			meta["command"] = cmd
			return event("command", cmd, meta)
		case first != "":
			return event(toolKind(tool), tool+" "+first, meta)
		}
		return event(toolKind(tool), openCodeToolText(tool, input), meta)
	case "completed":
		switch {
		case edit && first != "":
			meta["ok"] = true
			verb := "wrote "
			if deleted {
				verb = "deleted "
			}
			return event("result", verb+first, meta)
		case IsShellTool(tool):
			meta["command"] = cmd
			if exit, ok := state["exit"].(float64); ok {
				meta["ok"] = exit == 0 // OpenCode's bash says its exit code
			}
			return event("result", "ran "+cmd, meta)
		}
		return event("result", tool, meta)
	case "error":
		meta["ok"] = false
		text := tool + " failed"
		if IsShellTool(tool) && cmd != "" {
			meta["command"] = cmd
			text += " · " + cmd
		} else if first != "" {
			text += " · " + first
		}
		if e := strings.TrimSpace(strField(state, "error")); e != "" {
			text += ": " + firstLine(e)
		}
		return event("error", text, meta)
	}
	return nil
}

// openCodeToolText is a short line for one of OpenCode's own tools, never
// a JSON dump or a whole subagent prompt.
func openCodeToolText(tool string, input map[string]any) string {
	switch tool {
	case "todowrite":
		return claudeToolText("TodoWrite", input)
	case "task":
		if d := firstLine(strField(input, "description")); d != "" {
			return "task " + d
		}
		return "task"
	case "skill":
		return strings.TrimSpace("skill " + strField(input, "name"))
	}
	return claudeToolText(tool, input)
}

func init() {
	registerHarness(Harness{
		Name:    "opencode",
		Label:   "OpenCode",
		Config:  opencodePlugin,
		Present: func(home string) bool { return dirExists(opencodeDir(home)) },
		Wired: func(home string) bool {
			data, err := os.ReadFile(opencodePlugin(home))
			return err == nil && bytes.HasPrefix(data, []byte(opencodeMarker))
		},
		Install: func(home string, out io.Writer) error {
			if !dirExists(opencodeDir(home)) {
				fmt.Fprintf(out, "opencode: OpenCode isn't set up here (no %s); nothing changed\n", opencodeDir(home))
				return nil
			}
			return installOpenCode(opencodePlugin(home), out)
		},
		Uninstall: func(home string, out io.Writer) error { return uninstallOpenCode(opencodePlugin(home), out) },
	})
}
